// infographicFiles lists the files served for a card's infographic.
func infographicFiles(slug string) []string {
	return []string{
		"infographic-" + slug + ".jpg",
		"infographic-" + slug + "-teaser.jpg",
	}
}

// infographicVersions returns a short content hash of each configured card's
// infographic files, keyed by slug, for use as a ?v= cache-buster.
//
// Static files are served with only Last-Modified, so browsers cache them for a
// heuristic period. Replacing an image under the same URL would leave returning
// visitors on the old artwork beside the new "Figures checked" date. Hashing the
// content ties the URL to the bytes, whether or not anyone remembers to change
// Checked. A card whose files cannot be read is served unversioned.
func infographicVersions(staticDir string) map[string]string {
	versions := make(map[string]string, len(cardInfographics))
	// No image directory at all means no static assets in this environment (tests
	// with stub templates); only a missing file inside a real one is worth a warning.
	if _, err := os.Stat(filepath.Join(staticDir, "img")); err != nil {
		return versions
	}
	for slug := range cardInfographics {
		h := sha256.New()
		readable := true
		for _, name := range infographicFiles(slug) {
			b, err := os.ReadFile(filepath.Join(staticDir, "img", name))
			if err != nil {
				slog.Warn("infographic image unreadable; serving it unversioned", "slug", slug, "file", name, "error", err)
				readable = false
				break
			}
			h.Write(b)
		}
		if readable {
			versions[slug] = hex.EncodeToString(h.Sum(nil))[:12]
		}
	}
	return versions
}
